<script setup lang="ts">import{Head,Link}from'@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import{Button}from'@/components/ui/button';defineProps<{proposals:any[]}>();const money=(v:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v/100);</script><template><Head title="Sponsorship Proposals"/><div class="space-y-6 p-6"><div class="flex justify-between"><PageHeader title="Sponsorship Proposals" description="Build, send, accept, and convert sponsorship proposals."/><Link href="/admin/sponsorship-proposals/create"><Button>Create Proposal</Button></Link></div><div class="overflow-hidden rounded-xl border"><table class="w-full text-sm"><thead><tr><th class="p-3 text-left">Proposal</th><th>Advertiser</th><th>Status</th><th>Dates</th><th>Total</th></tr></thead><tbody><tr v-for="p in proposals" :key="p.id" class="border-t"><td class="p-3"><Link :href="`/admin/sponsorship-proposals/${p.id}`" class="font-medium hover:underline">{{p.title}}</Link><div>{{p.proposal_number}}</div></td><td>{{p.advertiser?.name}}</td><td>{{p.status}}</td><td>{{p.starts_on}} – {{p.ends_on}}</td><td>{{money(p.total_cents)}}</td></tr></tbody></table></div></div></template>